CREATE TABLE IF NOT EXISTS services(id TEXT PRIMARY KEY,name TEXT NOT NULL,option_name TEXT NOT NULL,sort_order INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS price_ranges(service_option_id TEXT REFERENCES services(id),vehicle_type TEXT NOT NULL,low REAL NOT NULL,typical REAL NOT NULL,high REAL NOT NULL,source TEXT NOT NULL,source_note TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(service_option_id,vehicle_type));
CREATE TABLE IF NOT EXISTS subscribers(id TEXT PRIMARY KEY,first_name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,zip TEXT NOT NULL,consent_at TEXT NOT NULL,consent_text TEXT NOT NULL,source TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quotes(id TEXT PRIMARY KEY,subscriber_id TEXT REFERENCES subscribers(id),service_option_id TEXT REFERENCES services(id),vehicle_year INTEGER NOT NULL,make TEXT NOT NULL,model TEXT NOT NULL,vehicle_type TEXT NOT NULL,amount REAL,shop_name TEXT,zip TEXT NOT NULL,status TEXT NOT NULL,flagged INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS quotes_pricing ON quotes(service_option_id,vehicle_type,status,created_at);
CREATE TABLE IF NOT EXISTS shops(id TEXT PRIMARY KEY,name TEXT NOT NULL,services TEXT NOT NULL,zips TEXT NOT NULL,contact TEXT NOT NULL,deal_text TEXT NOT NULL,deal_active INTEGER NOT NULL DEFAULT 0,vetted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS leads(id TEXT PRIMARY KEY,subscriber_id TEXT REFERENCES subscribers(id),quote_id TEXT REFERENCES quotes(id),phone TEXT NOT NULL,timing TEXT NOT NULL,consent_text TEXT NOT NULL,consent_at TEXT NOT NULL,status TEXT NOT NULL,buyer_shop_id TEXT REFERENCES shops(id),price_paid REAL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS checks(id TEXT PRIMARY KEY,payload TEXT NOT NULL,report TEXT NOT NULL,subscriber_id TEXT REFERENCES subscribers(id),quote_id TEXT REFERENCES quotes(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,name TEXT NOT NULL,campaign TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY,kind TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS service_content(service_id TEXT PRIMARY KEY,drivers TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS market_price_ranges(market TEXT NOT NULL,service_option_id TEXT REFERENCES services(id),vehicle_type TEXT NOT NULL,low REAL NOT NULL,typical REAL NOT NULL,high REAL NOT NULL,source_note TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(market,service_option_id,vehicle_type));
CREATE TABLE IF NOT EXISTS market_service_ranges(market TEXT NOT NULL,service_id TEXT NOT NULL,vehicle_type TEXT NOT NULL,low REAL NOT NULL,typical REAL NOT NULL,high REAL NOT NULL,source_note TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(market,service_id,vehicle_type));
CREATE TABLE IF NOT EXISTS partner_placements(shop_id TEXT PRIMARY KEY REFERENCES shops(id),paid_active INTEGER NOT NULL DEFAULT 0,market TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS intake_leads(id TEXT PRIMARY KEY,subscriber_id TEXT NOT NULL REFERENCES subscribers(id),service_id TEXT NOT NULL,phone TEXT NOT NULL,contact_text TEXT NOT NULL,newsletter_text TEXT NOT NULL,consent_at TEXT NOT NULL,source TEXT NOT NULL,vehicle_year INTEGER,make TEXT,model TEXT,desired_date TEXT,report TEXT,report_key TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS intake_quote_requests(intake_id TEXT PRIMARY KEY REFERENCES intake_leads(id),preferred_time TEXT NOT NULL,consent_text TEXT NOT NULL,consent_at TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS deals_signups(id TEXT PRIMARY KEY,email TEXT NOT NULL,first_name TEXT NOT NULL,service_id TEXT,created_at TEXT NOT NULL);
